// === Tab: mySketch ===
// Genuary 2023, Day 7: Sample a color palette from your favorite movie/album cover
// This generative piece was based on the album art of In Rainbows (2007) by Radiohead
// For #GenuaryTogether with
// https://twitter.com/DenisovichPy
// https://twitter.com/j0nasbo
// https://docs.google.com/spreadsheets/d/1QX2GVApwTXDG63Z8hFpnv3dYsT1LyXK6iaDGj5XAjkY/edit#gid=0

let r, buff, ws;
let lines = [];
let waves = [];
let randOffs = [];

let divs;

const PHI = 1.618033;

function setup() {
	l = max(windowWidth, windowHeight);
	createCanvas((w = l), (h = l));
	bg = createGraphics(w, h);
	seed = random(300000)
	r = random;
	divs = 12;

	ws = w / 5; //white space

	bg.blendMode(ADD); // BLEND, ADD, DIFFERENCE, MULTIPLY, OVERLAY
  for (let i = 0; i < l * 0.12345; i++) {
    let theta = random(TAU);
    let radius = random(w / 2);
    const x = w / 2 + radius * cos(theta);
    const y = h / 2 + radius * sin(theta);

    let area = r(40, 160);
    let amount = r(3, 6) * area;
    let weight = r(0.05, 0.15) * l;

    spotlight(bg, x, y, area, amount, weight);
  }

  let len = l - 2 * ws;
  let yStep = len / pal.length;


  // Wave parameter object data structure
  for (let i = 0; i < pal.length; i++) {
    const waveObj = {
      a1: random(TAU),
      b1: random(TAU),
      a2: random(TAU),
      b2: random(TAU),
      incr: [
        random(0.005, 0.04),
        random(0.005, 0.04),
        random(0.005, 0.04),
        random(0.005, 0.04),
      ],
      off: [0, 0, 0, 0],
    };
    waves.push(waveObj);
  }

  // Random offsets for rows
  for (let i = 0; i < pal.length; i++) {
  	randOffs.push(random([-1, 1]) * random(4))
  }
}

function draw() {
  randomSeed(seed);
  background(41);
  image(bg, 0, 0); // Draw the background

  var len = l - 2 * ws;
  var yStep = len / pal.length;
  for (let i = 0; i < pal.length; i++) {

    let w = waves[i];
    drawWave(
      { x: ws, y: yStep / 2 + ws + i * yStep },
      len,
      w.a1 + w.off[0],
      w.b1 + w.off[1],
      w.a2 + w.off[2],
      w.b2 + w.off[3],
      pal[i],
      i
    );
    for (let k = 0; k < 4; k++)
    	w.off[k] += w.incr[k];
  }
}

function drawWave(v1, len, a1, b1, a2, b2, col, num) {
  push();
  let unit = len / divs;
  translate(v1.x, v1.y);
  var x = unit / 2 + randOffs[num];
  let scl = 0.019 * l;

  stroke(col);
  strokeWeight(w/70);

  for (let i = 0; i < divs; i++) {
    let y1 = f(x, a1, b1) * scl;
    let y2 = f(x, a2, b2) * scl;
    if (r() < 0.8) line(x, y1, x, y2);
    x += unit;
  }
  pop();
}

let f = (x, a, b) => {
  return sin(2 * sin(PHI * x + b) + a);
};

function spotlight(buff, posX, posY, area, amount, weight) {
  let offset = weight / 4;
  buff.noStroke();
  let col = random(pal2);
  for (let i = 0; i < amount; i++) {
    buff.strokeWeight(weight);
    var x = randomGaussian(posX, area);
    var y = randomGaussian(posY, area);

    const randomWeight = weight + r([-1, 1]) * r(offset);
    const alpha = 1;
    buff.fill(red(window.color(col)), green(window.color(col)), blue(window.color(col)), alpha);
    buff.circle(x, y, randomWeight);
  }
}

// Utility
function randi(low, high) {
  return floor(random(low, high + 1));
}



const pal = [
  "#FBF04C",
  "#4688CB",
  "#F76321",
  "#44B649",
  "#ECB220",
  "#ED2526",
  "#A4DBE7",
];

const pal2 = [
	"#47096f", 
	"#0a1328", 
	"#df952a", 
	"#b8160d", 
	"#570007", 
	"#380371", 
	"DarkGreen"
];
